WITH base AS (SELECT * FROM subscriptions WHERE status IN ('PAUSED', 'CANCELLED') AND status != 'ACTIVE'), agg AS (SELECT DATE_FORMAT(end_date, 'yyyy-MM') AS end_month, SUM(CASE WHEN plan = 'premium' THEN monthly_fee ELSE 0 END) AS premium_monthly_fee FROM base GROUP BY DATE_FORMAT(end_date, 'yyyy-MM')) SELECT end_month, premium_monthly_fee FROM agg WHERE premium_monthly_fee > 70 ORDER BY premium_monthly_fee DESC;
